def fibonacci(n: int) -> int:
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def binary_search(arr: list, target: int) -> int:
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def flatten_nested_list(lst: list) -> list:
    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten_nested_list(item))
        else:
            result.append(item)
    return result

def merge_sorted_lists(l1: list, l2: list) -> list:
    result, i, j = [], 0, 0
    while i < len(l1) and j < len(l2):
        if l1[i] <= l2[j]:
            result.append(l1[i]); i += 1
        else:
            result.append(l2[j]); j += 1
    return result + l1[i:] + l2[j:]

def find_duplicates(lst: list) -> list:
    seen, dupes = set(), set()
    for x in lst:
        if x in seen:
            dupes.add(x)
        else:
            seen.add(x)
    return list(dupes)

def group_by(lst: list, key_fn) -> dict:
    result = {}
    for item in lst:
        k = key_fn(item)
        result.setdefault(k, []).append(item)
    return result

def parse_date_string(date_str: str) -> tuple:
    parts = date_str.split('-')
    return (int(parts[0]), int(parts[1]), int(parts[2]))

def longest_common_prefix(strs: list) -> str:
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix

def two_sum(nums: list, target: int) -> list:
    seen = {}
    for i, n in enumerate(nums):
        complement = target - n
        if complement in seen:
            return [seen[complement], i]
        seen[n] = i
    return []

def valid_parentheses(s: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack or stack[-1] != pairs[c]:
                return False
            stack.pop()
    return not stack

def rotate_matrix(matrix: list) -> list:
    n = len(matrix)
    return [[matrix[n - 1 - j][i] for j in range(n)] for i in range(n)]

def roman_to_integer(s: str) -> int:
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    for i in range(len(s)):
        if i + 1 < len(s) and vals[s[i]] < vals[s[i + 1]]:
            result -= vals[s[i]]
        else:
            result += vals[s[i]]
    return result

def word_frequency(text: str) -> dict:
    result = {}
    for word in text.split():
        result[word] = result.get(word, 0) + 1
    return result

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result, count = '', 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result += s[i - 1] + str(count)
            count = 1
    return result + s[-1] + str(count)

def sum_nested_dict(d: dict) -> float:
    total = 0
    for v in d.values():
        if isinstance(v, dict):
            total += sum_nested_dict(v)
        elif isinstance(v, (int, float)):
            total += v
    return total

def transpose_matrix(matrix: list) -> list:
    if not matrix:
        return []
    return [[matrix[r][c] for r in range(len(matrix))] for c in range(len(matrix[0]))]
